// Turn collection status into incidents. Only alarm inside an expected session window
// (a committed manifest exists and now is within OPEN-30m..CLOSE+15m). No session -> quiet.
const s = $json.status;
const now = new Date(s.now);
const sess = s.session;
const sid = sess ? sess.session_id : null;
let expected = false;
if (sess && sess.open_at && sess.close_at) {
  const openMs = new Date(sess.open_at).getTime() - 30 * 60 * 1000;
  const closeMs = new Date(sess.close_at).getTime() + 15 * 60 * 1000;
  const t = now.getTime();
  expected = t >= openMs && t <= closeMs;
}
const problems = [];
if (expected) {
  const health = s.health || [];
  for (const h of health) {
    if (h.status === 'outage') problems.push({ sig: `outage:${h.source}`, kind: 'stale_feed', severity: 'critical', detail: { source: h.source, status: h.status, checked_age_s: h.checked_age_s } });
    if (h.checked_age_s != null && h.checked_age_s > 180) problems.push({ sig: `heartbeat_stale:${h.source}`, kind: 'stale_feed', severity: 'error', detail: { source: h.source, checked_age_s: h.checked_age_s } });
    if (h.provider_age_s != null && Number(h.provider_age_s) > 120) problems.push({ sig: `provider_lag:${h.source}`, kind: 'stale_feed', severity: 'warn', detail: { source: h.source, provider_age_s: h.provider_age_s } });
    if (h.http_failures && h.http_failures > 0) problems.push({ sig: `http_failures:${h.source}`, kind: 'stale_feed', severity: 'warn', detail: { source: h.source, http_failures: h.http_failures } });
    if (h.missing_symbols && h.missing_symbols.length) problems.push({ sig: `missing_symbols:${h.source}`, kind: 'stale_feed', severity: 'warn', detail: { source: h.source, missing_symbols: h.missing_symbols } });
  }
  if (health.length === 0) problems.push({ sig: 'no_health', kind: 'stale_feed', severity: 'error', detail: { note: 'no source_health rows in the last hour during an active session window' } });
  const nb = s.newest_bar || {};
  if (nb.bar_end == null) problems.push({ sig: 'no_bars', kind: 'stale_feed', severity: 'error', detail: { note: 'no bars in the last day during an active session' } });
  else if (nb.age_s != null && Number(nb.age_s) > 180) problems.push({ sig: 'bar_gap', kind: 'stale_feed', severity: 'warn', detail: { newest_bar_end: nb.bar_end, age_s: nb.age_s } });
  for (const j of (s.jobs || [])) {
    if (j.status === 'failed') problems.push({ sig: `job_failed:${j.workflow}:${j.source}`, kind: 'stale_feed', severity: 'error', detail: { job: j } });
    else if (j.status === 'claimed' && j.lease_overdue_s != null && Number(j.lease_overdue_s) > 0) problems.push({ sig: `lease_overdue:${j.workflow}:${j.source}`, kind: 'stale_feed', severity: 'warn', detail: { job: j } });
  }
}
const openSigs = new Set((s.open_incidents || []).map(i => i.sig).filter(Boolean));
const problemSigs = new Set(problems.map(p => p.sig));
const toOpen = problems.filter(p => !openSigs.has(p.sig));
const toResolve = [...openSigs].filter(sig => !problemSigs.has(sig));
return [{ json: {
  session_id: sid,
  expected,
  new_incidents: toOpen.map(p => ({ session_id: sid, kind: p.kind, severity: p.severity, detail: JSON.stringify({ ...p.detail, sig: p.sig }) })),
  resolve_sigs: toResolve,
  summary: { expected, problems: problems.length, opening: toOpen.length, resolving: toResolve.length }
} }];

