INSERT INTO intraday.incidents (session_id, kind, severity, detail)
SELECT nullif(x.session_id,'')::uuid, x.kind, x.severity, x.detail::jsonb
FROM jsonb_to_recordset($1::jsonb) AS x(session_id text, kind text, severity text, detail text);

UPDATE intraday.incidents SET resolved_at = now()
WHERE resolved_at IS NULL AND detail->>'sig' IN (SELECT jsonb_array_elements_text($2::jsonb));
